groups={'common':common,'company':company,'branch':branch,'agency':agency}
for i,lang in enumerate(['en','fa','ps'],1):
 p=base/'src/i18n'/f'{lang}.ts';s=p.read_text(encoding='utf-8');marker=f'export const {lang} = {{';assert s.count(marker)==1
 data={g:{row[0]:row[i] for row in rows} for g,rows in groups.items()}
 block='  organizationRecords: '+json.dumps(data,ensure_ascii=False,indent=2)+',\n'
 s=s.replace(marker,marker+'\n'+block,1);p.write_text(s,encoding='utf-8')
maps={}
for group in ['company','branch','agency']:
 mapping={}
 for g in ['common',group]:
  for row in groups[g]:mapping[row[1]]='t.organizationRecords.'+g+'.'+row[0]
 if group=='company':
  for row in company:mapping[row[2]]='t.organizationRecords.company.'+row[0]
  mapping.update({'نام قانونی':'t.organizationRecords.company.legalName','نام تجاری':'t.organizationRecords.company.tradeName','وضعیت':'t.organizationRecords.common.status','اصلی':'t.organizationRecords.company.primary','اصلی Company':'t.organizationRecords.company.primary','فعال':'t.organizationRecords.common.active','غیرفعال':'t.organizationRecords.common.inactive','تعلیق‌شده':'t.organizationRecords.common.suspended','ویرایش شرکت':'t.organizationRecords.company.edit','افزودن شرکت':'t.organizationRecords.company.new'})
 for old in ([f'Edit {group}',f'Edit {group.title()}']):mapping[old]='t.organizationRecords.'+group+'.edit'
 mapping['Company ID']='t.organizationRecords.company.id' if group=='company' else mapping.get('Company ID','')
 mapping={k:v for k,v in mapping.items() if v}
 maps[group]=mapping
(dest/'translation-map.json').write_text(json.dumps(maps,ensure_ascii=False),encoding='utf-8')
print('Three translation catalogs extended with matching organizationRecords keys.')
